package gen:node;

world node {
    use aap:caps/types@0.1.0.{feed-item};

    import aap:caps/state-read@0.1.0;

    export run: func(items: list<feed-item>) -> list<feed-item>;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // DropSeen: keep only items whose id is not already recorded in the
        // 'seen' store. `id` is the parser-computed digest, safe as a store key.
        // Authority is StateHandle<'seen', read>: we may ask about a key we
        // already hold, never enumerate or mutate the store.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
